// ========================================
// CAPA 1: Definir fuentes RSS
// ========================================
// Cada fuente se convierte en un item.
// El nodo HTTP Request siguiente las procesa una por una.

const fuentes = [
  { url: 'https://news.mit.edu/topic/mitartificial-intelligence2-rss.xml', source: 'MIT News AI' },
  { url: 'https://sloanreview.mit.edu/feed/', source: 'MIT Sloan Review' },
  { url: 'https://www.cio.com/feed/', source: 'CIO.com' },
  { url: 'https://www.wired.com/feed/tag/ai/latest/rss', source: 'Wired AI' },
  { url: 'https://www.wired.com/feed/category/business/latest/rss', source: 'Wired Business' },
  { url: 'https://www.wired.com/feed/category/science/latest/rss', source: 'Wired Science' }
];

return fuentes.map(f => ({ json: f }));

// ========================================
// CAPA 1: Parsear RSS XML a JSON limpio
// ========================================
const items = $input.all();
const articulos = [];

for (const item of items) {
  const xml = typeof item.json.data === 'string' ? item.json.data : '';
  const source = item.json.source || 'Desconocido';

  // Extraer cada <item> del RSS
  const regex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
  let match;

  while ((match = regex.exec(xml)) !== null) {
    const block = match[1];

    // Extraer tag individual
    const tag = (name) => {
      const m = block.match(new RegExp('<' + name + '[^>]*>([\\s\\S]*?)</' + name + '>', 'i'));
      if (!m) return '';
      return m[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/<[^>]+>/g, '').trim();
    };

    const title = tag('title');
    const link = tag('link') || tag('guid');
    if (!title || !link) continue;

    articulos.push({
      title,
      link,
      description: tag('description').substring(0, 600),
      pubDate: tag('pubDate'),
      source
    });
  }
}

// Deduplicar por URL
const vistos = new Set();
const unicos = articulos.filter(a => {
  if (vistos.has(a.link)) return false;
  vistos.add(a.link);
  return true;
});

return [{ json: { articulos: unicos, total: unicos.length } }];

// ========================================
// CAPA 2: CONTEXT GRAPH + RAG
// ========================================
// Paso 1: Filtrar articulos ya publicados (Context Graph)
// Paso 2: Cargar identidad de marca (RAG)
// ORDEN: Context Graph PRIMERO, RAG DESPUES
// ========================================

const items = $input.all();

// --- Separar articulos nuevos de memoria existente ---
let articulosNuevos = [];
const topicosPublicados = new Set();
const bufferRechazados = [];

for (const item of items) {
  if (item.json.articulos) {
    articulosNuevos = item.json.articulos;
  } else if (item.json.topic) {
    // Viene de Google Sheets: memoria
    topicosPublicados.add(item.json.topic?.toLowerCase().trim());
    if (item.json.status === 'rejected') {
      bufferRechazados.push(item.json);
    }
  }
}

// --- CONTEXT GRAPH: Filtrar duplicados ---
const filtrados = articulosNuevos.filter(a => {
  const titleLower = a.title.toLowerCase();
  for (const topico of topicosPublicados) {
    // Si el titulo contiene un topico ya publicado, descartarlo
    if (topico && titleLower.includes(topico)) return false;
  }
  return true;
});

if (filtrados.length === 0) {
  return [{ json: { _sin_noticias: true } }];
}

// --- RAG: Identidad de Marca Aura Studio ---
const RAG = {
  marca: 'Aura Studio',
  filosofia: 'Work fast, live slow',
  audiencia: 'Directivos, lideres de industria y entusiastas de tecnologia en Latinoamerica',
  tono: 'Reflexivo, sofisticado, humano, calido. Habla de tu a tu con el directivo.',
  prohibido: 'Tech bros, vendedores agresivos, corporativos frios, emojis excesivos, clickbait',
  estetica: {
    estilo: 'Fotografia cinematografica editorial',
    naturaleza: 'Latinoamericana tropical: frailejones de paramo colombiano, monstera, orquideas, cafe, cacao, frutas tropicales, paisajes andinos',
    luz: 'Golden hour, neblina de montana, soft morning light',
    paleta: 'Verdes profundos, crema, beige, dorados sutiles',
    personas: 'Reales, diversas, en conexion con naturaleza',
    prohibido_visual: 'Robots, circuitos, neon, cyberpunk, oficinas genericas, estetica tech fria'
  },
  tipografia: 'Kaneda Gothic Medium/Bold para titulos',
  cta_permitidos: ['comenta', 'guarda', 'comparte'],
  formato_carrusel: {
    slides: '5-6 slides',
    slide_1: 'HOOK: Pregunta provocadora o dato impactante (max 8 palabras)',
    slide_2: 'CONTEXTO: Que esta pasando (max 30 palabras)',
    slide_3: 'IMPACTO: Por que importa al negocio (max 30 palabras)',
    slide_4: 'DATOS: Evidencia, estadistica o caso real (max 30 palabras)',
    slide_5: 'FUTURO: Que viene, que hacer ahora (max 30 palabras)',
    slide_6: 'CTA: Sigue a Aura Studio (opcional, solo si hay 6 slides)'
  }
};

return [{
  json: {
    articulos_filtrados: filtrados.slice(0, 10),
    total_disponibles: filtrados.length,
    context_graph: {
      topicos_publicados: Array.from(topicosPublicados),
      total_publicados_semana: topicosPublicados.size
    },
    rag: RAG
  }
}];

