// ========================================
// CAPA 3: GUARDRAILS
// ========================================
// Valida que el AI no alucine ni rompa la marca.
// Si algo falla, lo corrige automaticamente.
// ========================================

const aiRaw = $input.first().json;

// --- Paso 1: Extraer JSON del AI ---
let carrusel;
try {
  const content = aiRaw.choices?.[0]?.message?.content
    || aiRaw.message?.content
    || aiRaw.text || '';
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('AI no retorno JSON');
  carrusel = JSON.parse(jsonMatch[0]);
} catch (e) {
  return [{ json: {
    _error: true,
    mensaje: 'El AI no genero un JSON valido. Error: ' + e.message
  }}];
}

const problemas = [];
const slides = carrusel.slides || [];

// --- G1: Debe tener 5-6 slides ---
if (slides.length < 5) problemas.push('Menos de 5 slides (' + slides.length + ')');
if (slides.length > 6) {
  carrusel.slides = slides.slice(0, 6);
  problemas.push('Recortado a 6 slides (tenia ' + slides.length + ')');
}

// --- G2: Hook de portada max 10 palabras ---
if (slides[0] && slides[0].title) {
  const palabras = slides[0].title.split(/\s+/).length;
  if (palabras > 10) problemas.push('Hook muy largo: ' + palabras + ' palabras');
}

// --- G3: Body de cada slide max 40 palabras ---
for (const s of slides) {
  if (s.body && s.body.split(/\s+/).length > 40) {
    problemas.push('Slide ' + s.number + ': body excede 40 palabras');
  }
}

// --- G4: Prompts de imagen NO deben tener estetica tech ---
const prohibidas = ['robot', 'circuit', 'neon', 'cyberpunk', 'matrix', 'motherboard', 'generic office', 'binary'];
for (const s of slides) {
  if (s.image_prompt) {
    const lower = s.image_prompt.toLowerCase();
    for (const p of prohibidas) {
      if (lower.includes(p)) {
        s.image_prompt = s.image_prompt.replace(new RegExp(p, 'gi'), 'tropical nature');
        problemas.push('Slide ' + s.number + ': removido "' + p + '" del prompt');
      }
    }
  }
}

// --- G5: Hashtags obligatorios ---
if (!carrusel.hashtags) carrusel.hashtags = [];
if (!carrusel.hashtags.some(h => h.toLowerCase().includes('aurastudio'))) {
  carrusel.hashtags.unshift('#AuraStudio');
}
if (!carrusel.hashtags.some(h => h.toLowerCase().includes('workfastliveslow'))) {
  carrusel.hashtags.splice(1, 0, '#WorkFastLiveSlow');
}

// --- G6: CTA debe ser permitido ---
const ctaOk = ['comenta', 'guarda', 'comparte'];
if (!ctaOk.includes((carrusel.cta || '').toLowerCase())) {
  carrusel.cta = 'comenta';
  problemas.push('CTA ajustado a "comenta"');
}

// --- G7: Caption no vacio ---
if (!carrusel.caption || carrusel.caption.length < 10) {
  problemas.push('Caption muy corto o ausente');
}

// --- Construir mensaje Telegram ---
let msg = '🎨 *CARRUSEL GENERADO*\n\n';
msg += '📰 *' + (carrusel.meta?.topic || 'Sin titulo') + '*\n';
msg += '🔗 ' + (carrusel.meta?.source || '') + '\n';
msg += '⚡ Urgencia: ' + (carrusel.meta?.urgency || '-') + '\n\n';
msg += '📑 *Slides:*\n';
for (const s of carrusel.slides || []) {
  msg += s.number + '. [' + s.type + '] ' + s.title + '\n';
  if (s.body) msg += '   ' + s.body.substring(0, 60) + '\n';
}
msg += '\n✍️ *Caption:* ' + (carrusel.caption || '-') + '\n';
msg += '#️⃣ ' + (carrusel.hashtags || []).join(' ') + '\n';
msg += '🎯 CTA: ' + (carrusel.cta || '-') + '\n';

if (problemas.length > 0) {
  msg += '\n⚠️ *Guardrails:*\n';
  problemas.forEach(p => { msg += '  • ' + p + '\n'; });
}

msg += '\n---\n';
msg += '✅ *APROBAR* para publicar\n';
msg += '❌ *RECHAZAR* para descartar\n';
msg += '🔄 *REGENERAR* para nueva version';

return [{ json: {
  carrusel,
  carrusel_json: JSON.stringify(carrusel),
  telegram_msg: msg,
  guardrail_problemas: problemas,
  rejected: carrusel.rejected_articles || []
}}];

// Guardar articulos rechazados en buffer para el recap semanal
const data = $('7. Guardrails').first().json;
const rejected = data.rejected || [];

if (rejected.length === 0) {
  return [{ json: { _sin_rechazados: true, telegram_msg: data.telegram_msg } }];
}

// Retornar cada rechazado como item para append a sheets
const items = rejected.map(r => ({
  json: {
    topic: r.title || '',
    date: new Date().toISOString(),
    source: '',
    source_url: r.url || '',
    status: 'rejected',
    angle: r.reason || '',
    carrusel_json: ''
  }
}));

// Agregar el mensaje de telegram al ultimo item
items[items.length - 1].json.telegram_msg = data.telegram_msg;

return items;

// Encontrar el ultimo carrusel pendiente y marcarlo como publicado
const items = $input.all();
const chatId = $('Telegram Trigger').first().json.message?.chat?.id || 'TU_CHAT_ID';

// Buscar el ultimo con status=pending
const pendientes = items.filter(i => i.json.status === 'pending');
const ultimo = pendientes[pendientes.length - 1];

if (!ultimo) {
  return [{ json: { chat_id: chatId, msg: '⚠️ No hay carrusel pendiente de aprobacion.' } }];
}

return [{ json: {
  chat_id: chatId,
  topic: ultimo.json.topic,
  row_number: ultimo.json.row_number,
  msg: '✅ *Carrusel aprobado y guardado*\n\n📰 ' + ultimo.json.topic + '\n\nContext Graph actualizado. Listo para publicar.\n\n🌿 _Work fast, live slow_'
}}];

// Marcar ultimo pendiente como descartado
const items = $input.all();
const chatId = $('Telegram Trigger').first().json.message?.chat?.id || 'TU_CHAT_ID';
const pendientes = items.filter(i => i.json.status === 'pending');
const ultimo = pendientes[pendientes.length - 1];

if (!ultimo) {
  return [{ json: { chat_id: chatId, topic: '', msg: '⚠️ No hay carrusel pendiente.' } }];
}

return [{ json: {
  chat_id: chatId,
  topic: ultimo.json.topic,
  msg: '❌ *Carrusel rechazado*\n\n📰 ' + ultimo.json.topic + '\n\nMovido al buffer de descartes para el recap semanal.\n\nEscribe *REGENERAR* si quieres una nueva version.'
}}];

// Recuperar ultimo carrusel para regenerar
const items = $input.all();
const chatId = $('Telegram Trigger').first().json.message?.chat?.id || 'TU_CHAT_ID';
const pendientes = items.filter(i => i.json.status === 'pending' && i.json.carrusel_json);
const ultimo = pendientes[pendientes.length - 1];

if (!ultimo) {
  return [{ json: { chat_id: chatId, _error: true, msg: '⚠️ No hay carrusel para regenerar.' } }];
}

let carruselPrev;
try { carruselPrev = JSON.parse(ultimo.json.carrusel_json); } catch(e) { carruselPrev = {}; }

return [{ json: {
  chat_id: chatId,
  topic: ultimo.json.topic,
  source: ultimo.json.source,
  source_url: ultimo.json.source_url,
  carrusel_anterior: carruselPrev
}}];

